using System;
using System.Collections.Generic;
using System.Linq;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using LWS.TruckSports;
using LWS.TruckSports.Editor;
using LWS.TruckCheeseRolling;
namespace LWS.TruckKeepaway.Editor {
public static class KeepawayAuthoring {
 public const string Folder="TruckKeepaway",Scene="Assets/TruckKeepaway/Scenes/TruckKeepaway.unity";
 public static void Create(){System.IO.Directory.CreateDirectory("Assets/TruckKeepaway/Prefabs");AssetDatabase.Refresh();EditorSceneManager.OpenScene(LWS.TruckCheeseRolling.Editor.CheeseAuthoring.Scene);var cheese=UnityEngine.Object.FindAnyObjectByType<CheeseMatch>();var clips=cheese.feedback.clips;var blast=UnityEngine.Object.Instantiate(cheese.explosions[0].gameObject);blast.name="Keepaway comic blast · Cheese effect adapter";var template=PrefabUtility.SaveAsPrefabAsset(blast,"Assets/TruckKeepaway/Prefabs/ComicBlast.prefab");UnityEngine.Object.DestroyImmediate(blast);
  var m=SportsEventAuthoring.Begin<KeepawayMatch>(Folder);m.setup.count=4;m.feedback.clips=clips.Concat(new[]{AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/TruckBowling/Audio/Winner.wav")}).ToArray();var slate=SportsEventAuthoring.Mat(Folder,"Arena slate",new Color(.08f,.17f,.23f),.4f);var ivory=SportsEventAuthoring.Mat(Folder,"Arena white",new Color(.84f,.91f,.89f));var dark=SportsEventAuthoring.Mat(Folder,"Obstacle navy",new Color(.035f,.075f,.11f));var gold=SportsEventAuthoring.Mat(Folder,"Carrier gold",new Color(1,.8f,.1f),.65f);var contact=SportsEventAuthoring.Contact(Folder,"Arena contact",.7f,.08f);var rail=SportsEventAuthoring.Contact(Folder,"Barrier contact",.25f,.3f);
  SportsEventAuthoring.Box("Keepaway arena",new Vector3(0,-.3f,0),new Vector3(48,.6f,40),slate,contact);foreach(int sign in new[]{-1,1}){SportsEventAuthoring.Box("Side boundary",new Vector3(sign*23.5f,.6f,0),new Vector3(.6f,1.2f,40),ivory,rail);SportsEventAuthoring.Box("End boundary",new Vector3(0,.6f,sign*19.5f),new Vector3(48,1.2f,.6f),ivory,rail);}var obstacles=new List<Collider>();for(int i=0;i<4;i++){var g=GameObject.CreatePrimitive(PrimitiveType.Cylinder);g.name="Rounded cover bollard";g.transform.position=new Vector3(i%2==0?-7:7,.9f,i<2?-5:5);g.transform.localScale=new Vector3(2.8f,.9f,2.8f);g.GetComponent<Renderer>().sharedMaterial=dark;g.GetComponent<Collider>().sharedMaterial=rail;obstacles.Add(g.GetComponent<Collider>());}for(int sign=-1;sign<=1;sign+=2){var ramp=SportsEventAuthoring.Box("Broad escape ramp",new Vector3(sign*14,.35f,0),new Vector3(4,.45f,6),ivory,contact);ramp.transform.rotation=Quaternion.Euler(sign*12,0,0);obstacles.Add(ramp.GetComponent<Collider>());}m.obstacles=obstacles.ToArray();
  m.trucks=new SportsEventTruck[4];m.halos=new Transform[4];m.identities=new TextMesh[4];for(int i=0;i<4;i++){var t=SportsEventAuthoring.Truck(m,Folder,"Keepaway competitor "+(i+1),new Vector3(i%2==0?-15:15,.48f,i<2?-11:11),i);t.maxSpeed=14;t.motorTorque=7.5f;t.steerAngle=42;t.grip=1.4f;t.body.centerOfMass=new Vector3(0,-.08f,0);t.body.maxLinearVelocity=32;t.body.maxAngularVelocity=12;m.trucks[i]=t;var observer=t.gameObject.AddComponent<KeepawayContact>();observer.match=m;observer.slot=i;var halo=new GameObject("Carrier / protection ring "+i);var line=halo.AddComponent<LineRenderer>();line.useWorldSpace=false;line.sharedMaterial=gold;line.positionCount=41;line.startWidth=line.endWidth=.08f;for(int k=0;k<41;k++){float angle=k*Mathf.PI*2/40;line.SetPosition(k,new Vector3(Mathf.Cos(angle)*.5f,0,Mathf.Sin(angle)*.5f));}m.halos[i]=halo.transform;m.identities[i]=SportsEventAuthoring.Label("Participant identity "+i,m.setup.players[i].name,Vector3.zero,.2f,m.setup.players[i].color);}
  var ball=GameObject.CreatePrimitive(PrimitiveType.Sphere);ball.name="Single authoritative Keepaway ball";ball.layer=2;ball.transform.position=new Vector3(0,.85f,0);ball.transform.localScale=Vector3.one*1.3f;ball.GetComponent<Renderer>().sharedMaterial=gold;var body=ball.AddComponent<Rigidbody>();body.mass=1.5f;body.collisionDetectionMode=CollisionDetectionMode.ContinuousDynamic;body.interpolation=RigidbodyInterpolation.Interpolate;body.linearDamping=.12f;m.ball=body;m.ballShape=ball.GetComponent<SphereCollider>();m.ballShape.sharedMaterial=SportsEventAuthoring.Contact(Folder,"Ball contact",.1f,.55f);ball.AddComponent<KeepawayBall>().match=m;m.trail=ball.AddComponent<TrailRenderer>();m.trail.sharedMaterial=gold;m.trail.time=.45f;m.trail.startWidth=.2f;m.trail.endWidth=0;
  m.explosions=new ParticleSystem[4];for(int i=0;i<4;i++){var fx=(GameObject)PrefabUtility.InstantiatePrefab(template);fx.name="Pooled carrier blast "+i;m.explosions[i]=fx.GetComponent<ParticleSystem>();}m.debris=new CheeseDebris[24];for(int i=0;i<24;i++){var g=SportsEventAuthoring.Box("Pooled truck wreck chunk "+i,Vector3.zero,new Vector3(.5f,.35f,.8f),i%3==0?gold:dark,rail);g.layer=2;var b=g.AddComponent<Rigidbody>();b.mass=.25f;b.maxLinearVelocity=25;b.maxAngularVelocity=12;b.interpolation=RigidbodyInterpolation.Interpolate;b.collisionDetectionMode=CollisionDetectionMode.ContinuousDynamic;var d=g.AddComponent<CheeseDebris>();d.body=b;m.debris[i]=d;g.SetActive(false);}
  m.broadcast=SportsEventAuthoring.Camera("Keepaway shared arena camera");m.cameras=new[]{m.broadcast.view};m.broadcast.view.orthographic=true;m.broadcast.Pose(new Vector3(0,1,0),new Vector3(0,37,-18),60,true);var fit=m.broadcast.gameObject.AddComponent<SportsCameraFit>();fit.cameraTarget=m.broadcast.view;fit.arenaFit=true;fit.arenaBounds=new Bounds(new Vector3(0,2,0),new Vector3(49,10,41));fit.topInset=.09f;fit.bottomInset=.07f;fit.Apply();SportsEventAuthoring.UI(m);KeepawayChaosAuthoring.Install(m);KeepawayBoundaryAuthoring.Install(m);SportsEventAuthoring.Save(Folder);Validate();}
 public static void Validate(){EditorSceneManager.OpenScene(Scene);var m=UnityEngine.Object.FindAnyObjectByType<KeepawayMatch>();if(m==null||m.trucks.Length!=4||m.debris.Length!=24||m.explosions.Length!=4||m.ball==null||m.trucks.Any(t=>t.wheels.Length!=4)||m.feedback.clips.Any(c=>c==null)||UnityEngine.Object.FindObjectsByType<AudioListener>(FindObjectsInactive.Include).Length!=1)throw new Exception("Keepaway references incomplete");Debug.Log("KEEPAWAY_SAVED_VALIDATED");}
}
}
